const KEYWORDS = new Set(['let', 'if', 'else', 'while', 'return', 'true', 'false', 'null'])

const PUNCT2 = ['==', '!=', '<=', '>=', '&&', '||', '->', '=>']
const PUNCT1 = ['+', '-', '*', '/', '%', '=', '<', '>', '!', '(', ')', '{', '}', '[', ']', ',', ';', '.']

const TAB_WIDTH = 4

function isLetter(c) {
  return (c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z')
}

function isDecDigit(c) {
  return c !== undefined && c >= '0' && c <= '9'
}

function isIdentStart(c) {
  return c !== undefined && (isLetter(c) || c === '_')
}

function isIdentPart(c) {
  return c !== undefined && (isLetter(c) || isDecDigit(c) || c === '_')
}

function isHexDigit(c) {
  return c !== undefined && (isDecDigit(c) || (c >= 'a' && c <= 'f') || (c >= 'A' && c <= 'F'))
}

function digitTest(base) {
  if (base === 16) return isHexDigit
  if (base === 2) return (c) => c === '0' || c === '1'
  if (base === 8) return (c) => c !== undefined && c >= '0' && c <= '7'
  return isDecDigit
}

/** A cursor over the code points of the source, tracking line and column. */
class Cursor {
  constructor(text) {
    this.cps = Array.from(text)
    this.lines = new Array(this.cps.length)
    this.cols = new Array(this.cps.length)
    let line = 1
    let col = 1
    for (let i = 0; i < this.cps.length; i++) {
      this.lines[i] = line
      this.cols[i] = col
      const c = this.cps[i]
      if (c === '\n') {
        line += 1
        col = 1
      } else if (c === '\t') {
        col = Math.floor((col - 1) / TAB_WIDTH) * TAB_WIDTH + TAB_WIDTH + 1
      } else {
        col += 1
      }
    }
    this.endLine = line
    this.endCol = col
  }

  at(i) {
    return this.cps[i]
  }

  get length() {
    return this.cps.length
  }

  line(i) {
    return i < this.cps.length ? this.lines[i] : this.endLine
  }

  col(i) {
    return i < this.cps.length ? this.cols[i] : this.endCol
  }

  slice(from, to) {
    return this.cps.slice(from, to).join('')
  }

  fail(i, reason) {
    throw new ScanError(this.line(i), this.col(i), reason)
  }
}

/** Scans the source text and returns its tokens. */
export function scan(text) {
  const cur = new Cursor(text)
  const tokens = []
  let i = 0

  while (i < cur.length) {
    const c = cur.at(i)

    if (c === ' ' || c === '\t' || c === '\r' || c === '\n') {
      i += 1
      continue
    }

    if (c === '/' && cur.at(i + 1) === '/') {
      i += 2
      while (i < cur.length && cur.at(i) !== '\n') i += 1
      continue
    }

    if (c === '/' && cur.at(i + 1) === '*') {
      i = skipBlockComment(cur, i)
      continue
    }

    const start = i
    const line = cur.line(start)
    const column = cur.col(start)

    if (c === 'r' && cur.at(i + 1) === '"') {
      const result = scanRawString(cur, i)
      tokens.push({ line, column, kind: 'rawstring', text: result.text, value: result.value })
      i = result.next
      continue
    }

    if (isIdentStart(c)) {
      let j = i + 1
      while (isIdentPart(cur.at(j))) j += 1
      const word = cur.slice(i, j)
      tokens.push({ line, column, kind: KEYWORDS.has(word) ? 'keyword' : 'ident', text: word })
      i = j
      continue
    }

    if (isDecDigit(c)) {
      const result = scanNumber(cur, i)
      tokens.push({ line, column, kind: 'number', text: result.text })
      i = result.next
      continue
    }

    if (c === '"') {
      const result = scanString(cur, i)
      tokens.push({ line, column, kind: 'string', text: result.text, value: result.value })
      i = result.next
      continue
    }

    const two = cur.slice(i, i + 2)
    if (PUNCT2.includes(two)) {
      tokens.push({ line, column, kind: 'punct', text: two })
      i += 2
      continue
    }

    if (PUNCT1.includes(c)) {
      tokens.push({ line, column, kind: 'punct', text: c })
      i += 1
      continue
    }

    cur.fail(i, `unexpected character ${c}`)
  }

