      } else if ((sign === '+' || sign === '-') && isDecDigit(cur.at(i + 2))) {
        i = scanDigitRun(cur, i + 2, 10)
      }
    }
  }

  if (isIdentPart(cur.at(i))) failNumber(cur, start, i)

  return { text: cur.slice(start, i), next: i }
