  const isDigit = digitTest(base)
  let j = i
  while (j < cur.length) {
    const c = cur.at(j)
    if (isDigit(c)) {
      j += 1
      continue
    }
    if (c === '_' && j > i && isDigit(cur.at(j - 1)) && isDigit(cur.at(j + 1))) {
      j += 1
      continue
    }
    break
  }
  return j
