  let i = start + 2
  while (i < cur.length && cur.at(i) !== '"') i += 1
  if (i >= cur.length) cur.fail(start, 'unterminated string')
  return { text: cur.slice(start, i + 1), value: cur.slice(start + 2, i), next: i + 1 }
