  let i = start + 1
  let value = ''
  while (true) {
    if (i >= cur.length) cur.fail(start, 'unterminated string')
    const c = cur.at(i)
    if (c === '"') {
      return { text: cur.slice(start, i + 1), value, next: i + 1 }
    }
    if (c === '\n') cur.fail(i, 'newline in string')
    if (c !== '\\') {
      value += c
      i += 1
      continue
    }
    const escape = cur.at(i + 1)
    if (escape === undefined) cur.fail(start, 'unterminated string')
    const bad = () => cur.fail(i, `invalid escape \\${escape}`)
    if (escape === 'n') value += '\n'
    else if (escape === 't') value += '\t'
    else if (escape === 'r') value += '\r'
    else if (escape === '\\') value += '\\'
    else if (escape === '"') value += '"'
    else if (escape === '0') value += '\0'
