/**
 * The command. `node src/cli.js tokens` prints every token of the source read
 * from standard input with its position, and `node src/cli.js stats` counts the
 * tokens by kind.
 */

import { readFileSync } from 'node:fs'
import { scan, ScanError } from './lexer.js'

const KINDS = ['ident', 'keyword', 'number', 'punct', 'rawstring', 'string']

function fail(message) {
  process.stderr.write(`error: ${message}\n`)
  process.exit(2)
}

function readStdin() {
  try {
    return readFileSync(0, 'utf8')
  } catch {
    return ''
  }
}

function main(argv) {
  const mode = argv.length === 1 ? argv[0] : undefined
  if (mode !== 'tokens' && mode !== 'stats') fail('usage: cli.js tokens|stats')

  let tokens
  try {
    tokens = scan(readStdin())
  } catch (error) {
    if (error instanceof ScanError) fail(error.message)
    throw error
  }

  const lines = []
  if (mode === 'tokens') {
    for (const token of tokens) {
      const body =
        token.kind === 'string' || token.kind === 'rawstring'
          ? JSON.stringify(token.value)
          : token.text
      lines.push(`${token.line}:${token.column} ${token.kind} ${body}`)
    }
  } else {
    for (const kind of KINDS) {
      lines.push(`${kind} ${tokens.filter((token) => token.kind === kind).length}`)
    }
    lines.push(`total ${tokens.length}`)
  }

  process.stdout.write(lines.map((line) => `${line}\n`).join(''))
}

main(process.argv.slice(2))
